+impl<'a> PickRequest<'a> {
+    pub fn new(model: &'a ModelId, stage: Stage, input_tokens: u64) -> Self {
+        Self {
+            model,
+            stage,
+            bucket: "",
+            input_tokens,
+            expected_peak_tokens: None,
+            prefix: None,
+            token_ids: None,
+            session_key: None,
+            routing_key: None,
