+        bucket("tps", 10, 2, Some(100), Some(100.0)),
+        bucket("neither", 8, 0, Some(100), Some(10.0)),
+        bucket("missing", 10, 3, None, None),
+        bucket("too-short", 1, 0, Some(1), Some(1000.0)),
+    ])
+    .unwrap()
+}
