+        const auto r0 = cast<fp32x2_t>(residual[0][k]);
+        const auto r1 = cast<fp32x2_t>(residual[1][k]);
+        const auto r2 = cast<fp32x2_t>(residual[2][k]);
+        const auto r3 = cast<fp32x2_t>(residual[3][k]);
