+        float b = __fmaf_rn(post, xx.y, __fmul_rn(c0, r0.y));
+        a = __fmaf_rn(c1, r1.x, a);
+        b = __fmaf_rn(c1, r1.y, b);
+        a = __fmaf_rn(c2, r2.x, a);
+        b = __fmaf_rn(c2, r2.y, b);
+        a = __fmaf_rn(c3, r3.x, a);
+        b = __fmaf_rn(c3, r3.y, b);
