+        else {
+          sum = __fmaf_rn(value.x, value.x, sum);
+          sum = __fadd_rn(__fmul_rn(value.y, value.y), sum);
+        }
+      }
+    }
+#pragma unroll
+    for (int offset = 16; offset; offset >>= 1)
+      sum = __fadd_rn(sum, __shfl_xor_sync(0xffffffff, sum, offset));
