+        let extras = collected.extras.unwrap();
+        assert_eq!(extras.output_logprobs[0].token.token_id, 1);
+        assert_eq!(extras.output_logprobs[1].token.token_id, 2);
+        assert_eq!(extras.input_logprobs[0].token.token_id, 20);
