+        let client = HttpGenerateClient::new(format!("http://{address}")).unwrap();
+        let app = standalone_routes(
+            OpenAIService::new(
+                renderer,
+                GenerationService::new(Arc::new(client.clone()), TokenDecoder::new(tokenizer)),
+            ),
+            client,
+        );
+        let response = tokio::time::timeout(
+            Duration::from_secs(2),
+            post_request(
+                app,
+                "/v1/completions",
+                &serde_json::json!({
+                    "model": "model",
+                    "prompt": "hello",
+                    "n": 2
+                }),
+            ),
+        )
+        .await
+        .expect("both engine requests must be submitted before either responds");
+        engine.abort();
+
+        assert_eq!(response.status(), StatusCode::OK);
+        assert_eq!(engine_state.max_active.load(Ordering::SeqCst), 2);
+        let body: serde_json::Value =
+            serde_json::from_slice(&to_bytes(response.into_body(), 64 * 1024).await.unwrap())
+                .unwrap();
+        assert_eq!(body["choices"][0]["index"], 0);
+        assert_eq!(body["choices"][0]["matched_stop"], 10);
+        assert_eq!(body["choices"][1]["index"], 1);
+        assert_eq!(body["choices"][1]["matched_stop"], 11);
+    }
+}

