+fn reject_unsupported_fields(fields: &HashMap<String, Value>) -> Result<(), String> {
+    if fields.is_empty() {
+        return Ok(());
+    }
+    let mut names = fields.keys().cloned().collect::<Vec<_>>();
+    names.sort_unstable();
+    Err(format!(
+        "unsupported request field{}: {}",
+        if names.len() == 1 { "" } else { "s" },
+        names.join(", ")
+    ))
+}
