+                    }
+                }
+            }
+            assert_eq!(texts, [if chat { "h" } else { "helloh" }; 2]);
+            assert_eq!(finished, [true; 2]);
+        }
+    }
+    let requests = transport.0.lock().unwrap();
+    assert_eq!(requests.len(), 8);
+    assert!(requests.iter().all(|request| !request.input_ids.is_empty()));
