+    match reason {
+        ChatFinishReason::Stop => FinishReason::Stop,
+        ChatFinishReason::Length => FinishReason::Length,
+        ChatFinishReason::ContentFilter => FinishReason::ContentFilter,
+        ChatFinishReason::ToolCalls => FinishReason::ToolCalls,
