+fn build_reasoning_parser(server_name: &str) -> ReasoningParserWrapper {
+    let name = match server_name {
+        "deepseek-r1" | "step3p5" => "deepseek_r1",
+        "kimi_k2" => "kimi_k25",
+        "gpt-oss" => "gpt_oss",
+        "nemotron_3" => "nemotron3",
+        "interns1" => "qwen3",
+        "qwen3-thinking" | "minimax" => "deepseek_r1",
+        _ => server_name,
