+    pub reasoning_effort: Option<ReasoningEffort>,
+    pub continue_final_message: bool,
+    pub chat_template_args: Option<HashMap<String, serde_json::Value>>,
+    pub sampling_params: SamplingParams,
+    pub choice_count: usize,
+    pub stream: bool,
